// Constexpr static member of a quantity of TFEL (a class type) used in
// device code, as in the code generated by MFront for a static variable
// (`@StaticVariable`) of a behaviour using quantities (`@UseQt true`).
//
// nvcc rejects a reference to such a member in device code ("identifier is
// undefined in device code"): an operator taking its arguments by reference
// in an expression evaluated at run time binds a reference to it. A copy
// built at compile time can be used.
//
// MODE: 1 for the static member itself (code generated by MFront before
// the correction), 2 for the copy `decltype(v){v}`, 3 for an expression
// evaluated at compile time, without copy, 4 for the macro
// `TFEL_STATIC_VARIABLE` written by MFront since the correction (the
// variable itself in host code, the copy in device code).
#include "TFEL/Config/TFELTypes.hxx"
#include "TFEL/Math/qt.hxx"

using temperature = tfel::math::qt<tfel::math::unit::Temperature, double>;

template <int N>
struct Behaviour {
  static constexpr auto Tref = temperature{293.15};
  __host__ __device__ static double integrate(const temperature T) {
#if MODE == 1
    const auto d = T - Behaviour::Tref;
#elif MODE == 2
    const auto d = T - decltype(Behaviour::Tref){Behaviour::Tref};
#elif MODE == 3
    constexpr auto twice = 2 * Behaviour::Tref;
    const auto d = T - twice;
#elif MODE == 4
    const auto d = T - TFEL_STATIC_VARIABLE(Behaviour::Tref);
#endif
    return d.getValue();
  }
};

__global__ void kernel(double* const r) {
  r[0] = Behaviour<0>::integrate(temperature{300.});
}

int main() { return 0; }
